// frontend/src/pages/Auth.js
// Login with Google Authenticator 2FA · No public registration

import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

// ── AUTH WRAPPER BOX ─────────────────────────────────────────────────────────
function AuthBox({ children, wide }) {
  return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center',
      background:'var(--bv-bg)', padding:16 }}>
      <div style={{ width:'100%', maxWidth: wide ? 480 : 400,
        background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)',
        borderRadius:14, boxShadow:'0 8px 40px rgba(0,0,0,0.3)' }}>

        {/* Logo header */}
        <div style={{ padding:'22px 28px 18px', textAlign:'center',
          borderBottom:'1px solid var(--bv-bd)' }}>
          <div style={{ width:48, height:48,
            background:'linear-gradient(135deg,var(--bv-accent),var(--bv-accent-dark))',
            borderRadius:12, display:'flex', alignItems:'center', justifyContent:'center',
            margin:'0 auto 12px', fontSize:18, fontWeight:700, color:'#fff' }}>BV</div>
          <div style={{ fontSize:19, fontWeight:600, color:'var(--bv-txt)', lineHeight:1 }}>BackupVault</div>
          <div style={{ fontSize:11.5, color:'var(--bv-cyan)', marginTop:4, fontWeight:500 }}>
            Infrastructure · Worktual Innovations
          </div>
        </div>

        <div style={{ padding:'22px 28px 26px' }}>{children}</div>
      </div>
    </div>
  );
}

function ErrBox({ msg }) {
  if (!msg) return null;
  return <div style={{ color:'var(--bv-red)', fontSize:12, marginBottom:12,
    padding:'8px 12px', background:'var(--bv-red-bg)', borderRadius:7,
    border:'1px solid var(--bv-red-border)', display:'flex', alignItems:'center', gap:8 }}>
    <i className="ti ti-alert-circle" style={{ fontSize:14, flexShrink:0 }}/>
    {msg}
  </div>;
}

function OkBox({ msg }) {
  if (!msg) return null;
  return <div style={{ color:'var(--bv-green)', fontSize:12, marginBottom:12,
    padding:'8px 12px', background:'var(--bv-green-bg)', borderRadius:7,
    border:'1px solid var(--bv-green)', display:'flex', alignItems:'center', gap:8 }}>
    <i className="ti ti-circle-check" style={{ fontSize:14, flexShrink:0 }}/>
    {msg}
  </div>;
}

function FormField({ label, hint, required, children }) {
  return <div style={{ marginBottom:14 }}>
    <label style={{ fontSize:11.5, fontWeight:600, color:'var(--bv-txt2)',
      display:'block', marginBottom:5, letterSpacing:'.02em' }}>
      {label}{required && <span style={{ color:'var(--bv-red)', marginLeft:2 }}>*</span>}
      {hint && <span style={{ fontWeight:400, color:'var(--bv-txt3)', marginLeft:6 }}>{hint}</span>}
    </label>
    {children}
  </div>;
}

function SubmitBtn({ loading, children, ...rest }) {
  return <button {...rest}
    disabled={loading || rest.disabled}
    style={{ width:'100%', padding:'10px 0', background:'var(--bv-accent)', color:'#fff',
      border:'none', borderRadius:9, fontSize:13.5, fontWeight:600, cursor:loading?'wait':'pointer',
      display:'flex', alignItems:'center', justifyContent:'center', gap:8,
      opacity: loading ? 0.75 : 1, transition:'opacity .15s',
      marginBottom:10, ...rest.style }}>
    {loading
      ? <><i className="ti ti-loader" style={{ animation:'bvspin .7s linear infinite', fontSize:15 }}/> Please wait...</>
      : children}
  </button>;
}

// ── MAIN LOGIN PAGE ───────────────────────────────────────────────────────────
export function LoginPage() {
  const [view,      setView]     = useState('login'); // login | totp | forgot | otp | reset
  const [form,      setForm]     = useState({ email:'', password:'' });
  const [totp,      setTotp]     = useState('');
  const [totpEmail, setTotpEmail]= useState('');
  const [forgot,    setForgot]   = useState('');
  const [otp,       setOtp]      = useState({ code:'', newPass:'', confirm:'' });
  const [loading,   setLoading]  = useState(false);
  const [error,     setError]    = useState('');
  const [msg,       setMsg]      = useState('');
  const [showPass,  setShowPass] = useState(false);
  const totpRefs = [useRef(), useRef(), useRef(), useRef(), useRef(), useRef()];
  const { login, loginWithToken } = useAuth();
  const navigate = useNavigate();

  // ── Login handler ───────────────────────────────────────────────────────
  async function handleLogin(e) {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const res = await login(form.email.trim(), form.password);
      if (res?.requires_2fa) {
        setTotpEmail(form.email.trim());
        setView('totp');
        return;
      }
      navigate('/dashboard');
    } catch(err) { setError(err.message); }
    finally { setLoading(false); }
  }

  // ── TOTP handler ────────────────────────────────────────────────────────
  async function handleTotp(e) {
    e.preventDefault();
    if (totp.length !== 6) { setError('Enter all 6 digits'); return; }
    setError(''); setLoading(true);
    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: totpEmail, password: form.password, totp_code: totp }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
      loginWithToken(data);
      navigate('/dashboard');
    } catch(err) {
      setError(err.message);
      setTotp('');
    }
    finally { setLoading(false); }
  }

  // ── Forgot password ─────────────────────────────────────────────────────
  async function handleForgot(e) {
    e.preventDefault(); setError(''); setLoading(true);
    try {
      const res = await fetch('/api/auth/forgot-password', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ email: forgot.trim() }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error);
      setMsg('OTP sent to your email. Check inbox.'); setView('otp');
    } catch(err) { setError(err.message); }
    finally { setLoading(false); }
  }

  // ── Reset with OTP ──────────────────────────────────────────────────────
  async function handleReset(e) {
    e.preventDefault();
    if (otp.newPass !== otp.confirm) { setError('Passwords do not match'); return; }
    if (otp.newPass.length < 8)      { setError('Password must be at least 8 characters'); return; }
    setError(''); setLoading(true);
    try {
      const res = await fetch('/api/auth/reset-password-with-otp', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ email: forgot, otp: otp.code, newPassword: otp.newPass }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error);
      setMsg('Password reset. Please sign in.'); setView('login');
      setForm(p => ({ ...p, email: forgot, password: '' }));
    } catch(err) { setError(err.message); }
    finally { setLoading(false); }
  }

  function goLogin() { setView('login'); setError(''); setMsg(''); setTotp(''); }

  // ── VIEW: TOTP ────────────────────────────────────────────────────────────
  if (view === 'totp') return (
    <AuthBox>
      <div style={{ textAlign:'center', marginBottom:20 }}>
        <div style={{ width:56, height:56, borderRadius:'50%',
          background:'var(--bv-blue-dim)', border:'2px solid var(--bv-blue)',
          display:'flex', alignItems:'center', justifyContent:'center',
          margin:'0 auto 14px', fontSize:28 }}>🔐</div>
        <div style={{ fontSize:16, fontWeight:600, color:'var(--bv-txt)', marginBottom:6 }}>
          Two-Factor Authentication
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)', lineHeight:1.6 }}>
          Open <strong>Google Authenticator</strong> on your phone<br/>
          and enter the 6-digit code for<br/>
          <span style={{ color:'var(--bv-cyan)', fontWeight:500 }}>{totpEmail}</span>
        </div>
      </div>

      <form onSubmit={handleTotp}>
        {/* 6-box OTP input */}
        <div style={{ display:'flex', gap:8, justifyContent:'center', marginBottom:18 }}>
          {[0,1,2,3,4,5].map(i => (
            <input key={i} ref={totpRefs[i]}
              type="text" inputMode="numeric" maxLength={1}
              value={totp[i]||''}
              onChange={e => {
                const v = e.target.value.replace(/\D/g,'');
                const arr = totp.split('');
                arr[i] = v; setTotp(arr.join('').slice(0,6));
                if (v && i < 5) totpRefs[i+1].current?.focus();
              }}
              onKeyDown={e => {
                if (e.key==='Backspace' && !totp[i] && i>0) totpRefs[i-1].current?.focus();
                if (e.key==='ArrowLeft'  && i>0) totpRefs[i-1].current?.focus();
                if (e.key==='ArrowRight' && i<5) totpRefs[i+1].current?.focus();
              }}
              onPaste={e => {
                e.preventDefault();
                const v = e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6);
                setTotp(v.padEnd(6,'').slice(0,6));
                if (v.length>0) totpRefs[Math.min(v.length-1,5)].current?.focus();
              }}
              style={{ width:44, height:52, textAlign:'center', fontSize:22, fontWeight:700,
                fontFamily:'monospace', background:'var(--bv-input)', color:'var(--bv-txt)',
                border:`2px solid ${totp[i]?'var(--bv-blue)':'var(--bv-bd2)'}`,
                borderRadius:9, outline:'none', transition:'border-color .15s',
                caretColor:'transparent' }}
              autoFocus={i===0}/>
          ))}
        </div>

        <ErrBox msg={error}/>

        <SubmitBtn loading={loading} disabled={totp.length!==6}>
          <i className="ti ti-shield-check" style={{ fontSize:16 }}/> Verify & Sign In
        </SubmitBtn>

        <div style={{ padding:'10px 12px', background:'var(--bv-bg3)', borderRadius:8,
          fontSize:11.5, color:'var(--bv-txt2)', marginBottom:12, lineHeight:1.6 }}>
          <i className="ti ti-info-circle" style={{ color:'var(--bv-blue)', marginRight:6 }}/>
          <strong>Lost your phone?</strong> Use one of your 10 backup codes instead.
          Enter the backup code (format: <span style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>XXXX-XXXX</span>) in the boxes above.
        </div>

        <button type="button" onClick={goLogin}
          style={{ background:'none', border:'none', color:'var(--bv-blue)', fontSize:12,
            width:'100%', textAlign:'center', cursor:'pointer', padding:'4px 0' }}>
          <i className="ti ti-arrow-left" style={{ marginRight:5 }}/>Back to sign in
        </button>
      </form>
    </AuthBox>
  );

  // ── VIEW: FORGOT PASSWORD ─────────────────────────────────────────────────
  if (view === 'forgot') return (
    <AuthBox>
      <div style={{ marginBottom:18 }}>
        <div style={{ fontSize:16, fontWeight:600, color:'var(--bv-txt)', marginBottom:4 }}>
          Forgot password
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)' }}>
          Enter your email and we'll send a one-time reset code
        </div>
      </div>
      <form onSubmit={handleForgot}>
        <FormField label="Email address" required>
          <input type="email" value={forgot} onChange={e=>setForgot(e.target.value)}
            placeholder="admin@worktual.tech" style={{ width:'100%' }} required autoFocus/>
        </FormField>
        <ErrBox msg={error}/><OkBox msg={msg}/>
        <SubmitBtn loading={loading}>Send Reset OTP</SubmitBtn>
        <button type="button" onClick={goLogin} style={{ background:'none', border:'none',
          color:'var(--bv-blue)', fontSize:12, width:'100%', textAlign:'center', cursor:'pointer' }}>
          <i className="ti ti-arrow-left" style={{ marginRight:5 }}/>Back to sign in
        </button>
      </form>
    </AuthBox>
  );

  // ── VIEW: RESET WITH OTP ──────────────────────────────────────────────────
  if (view === 'otp') return (
    <AuthBox>
      <div style={{ marginBottom:18 }}>
        <div style={{ fontSize:16, fontWeight:600, color:'var(--bv-txt)', marginBottom:4 }}>
          Reset password
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)' }}>
          Enter the 6-digit code sent to <strong style={{ color:'var(--bv-cyan)' }}>{forgot}</strong>
        </div>
      </div>
      <form onSubmit={handleReset}>
        <FormField label="OTP Code" required>
          <input value={otp.code} onChange={e=>setOtp(p=>({...p,code:e.target.value.slice(0,6)}))}
            placeholder="123456" maxLength={6}
            style={{ width:'100%', textAlign:'center', fontFamily:'monospace', fontSize:20,
              letterSpacing:6, fontWeight:600 }} autoFocus required/>
        </FormField>
        <FormField label="New password" required hint="Min. 8 characters">
          <input type="password" value={otp.newPass} onChange={e=>setOtp(p=>({...p,newPass:e.target.value}))}
            style={{ width:'100%' }} required minLength={8}/>
        </FormField>
        <FormField label="Confirm new password" required>
          <input type="password" value={otp.confirm} onChange={e=>setOtp(p=>({...p,confirm:e.target.value}))}
            style={{ width:'100%' }} required/>
        </FormField>
        <ErrBox msg={error}/><OkBox msg={msg}/>
        <SubmitBtn loading={loading}>Reset Password</SubmitBtn>
        <button type="button" onClick={goLogin} style={{ background:'none', border:'none',
          color:'var(--bv-blue)', fontSize:12, width:'100%', textAlign:'center', cursor:'pointer' }}>
          <i className="ti ti-arrow-left" style={{ marginRight:5 }}/>Back to sign in
        </button>
      </form>
    </AuthBox>
  );

  // ── VIEW: MAIN LOGIN ──────────────────────────────────────────────────────
  return (
    <AuthBox>
      <div style={{ fontSize:15.5, fontWeight:600, color:'var(--bv-txt)', marginBottom:18 }}>
        Sign in to your account
      </div>

      <form onSubmit={handleLogin}>
        <FormField label="Email address" required>
          <input type="email" value={form.email}
            onChange={e=>setForm(p=>({...p,email:e.target.value}))}
            placeholder="admin@worktual.tech" style={{ width:'100%' }} required autoFocus/>
        </FormField>

        <FormField label="Password" required>
          <div style={{ position:'relative' }}>
            <input type={showPass?'text':'password'} value={form.password}
              onChange={e=>setForm(p=>({...p,password:e.target.value}))}
              style={{ width:'100%', paddingRight:38 }} required/>
            <button type="button" onClick={()=>setShowPass(v=>!v)}
              style={{ position:'absolute', right:10, top:'50%', transform:'translateY(-50%)',
                background:'none', border:'none', color:'var(--bv-txt3)', cursor:'pointer', padding:2 }}>
              <i className={`ti ti-${showPass?'eye-off':'eye'}`} style={{ fontSize:16 }}/>
            </button>
          </div>
        </FormField>

        <ErrBox msg={error}/><OkBox msg={msg}/>

        <SubmitBtn loading={loading}>
          <i className="ti ti-login" style={{ fontSize:16 }}/> Sign In
        </SubmitBtn>
      </form>

      <button onClick={()=>{setView('forgot');setError('');setMsg('');}}
        style={{ background:'none', border:'none', color:'var(--bv-blue)', fontSize:12,
          cursor:'pointer', padding:'0 0 14px', display:'block' }}>
        Forgot password?
      </button>

      {/* 2FA notice */}
      <div style={{ padding:'10px 12px', background:'var(--bv-bg3)', borderRadius:8,
        fontSize:11, color:'var(--bv-txt3)', lineHeight:1.7 }}>
        <i className="ti ti-shield-lock" style={{ marginRight:6, color:'var(--bv-blue)' }}/>
        If your account has Google Authenticator enabled, you'll be asked for a
        6-digit code after your password.
      </div>

      <div style={{ marginTop:16, paddingTop:14, borderTop:'1px solid var(--bv-bd)',
        fontSize:11, color:'var(--bv-txt3)', textAlign:'center' }}>
        <i className="ti ti-lock" style={{ marginRight:5 }}/>
        Access by invitation only. Contact your administrator.
      </div>
    </AuthBox>
  );
}

// /register redirects to /login — no public self-registration
export function RegisterPage() {
  const navigate = useNavigate();
  useEffect(() => { navigate('/login', { replace:true }); }, [navigate]);
  return null;
}
